type Principal = { userId: string; roles: string[] } | null;

function decide(principal: Principal, action: string, ownerId: string, requesterId: string) {
  // Gate 1 — AUTHENTICATION: is there a verified principal at all?
  if (!principal) return { allow: false, status: 401, reason: "not authenticated" };
  // Gate 2 — AUTHORIZATION: may THIS principal do THIS action?
  const isOwner = principal.userId === ownerId;
  const isAdmin = principal.roles.includes("admin");
  if (action === "delete" && !isOwner && !isAdmin) {
    return { allow: false, status: 403, reason: "forbidden: not owner or admin" };
  }
  return { allow: true, status: 200, reason: "ok" };
}

