type Ctx = { principal: { userId: string; roles: string[] } | null };
type Result = { status: number; body: string };

const requireAuth = (ctx: Ctx): Result | null =>
  ctx.principal ? null : { status: 401, body: "unauthenticated" };

const requireRole = (role: string) => (ctx: Ctx): Result | null =>
  ctx.principal?.roles.includes(role) ? null : { status: 403, body: "forbidden" };

function runChain(ctx: Ctx, chain: ((c: Ctx) => Result | null)[], handler: (c: Ctx) => Result) {
  for (const mw of chain) {
    const stop = mw(ctx);       // a middleware may short-circuit
    if (stop) return stop;      // 401/403 -> handler never runs
  }
  return handler(ctx);          // both gates passed
}

