import crypto from "node:crypto";

function verifyStripeSignature(rawBody: string, header: string, secret: string, nowSec: number, toleranceSec = 300) {
  // header: "t=1700000000,v1=abc123..."
  const parts = Object.fromEntries(header.split(",").map(kv => kv.split("=")));
  const timestamp = Number(parts.t);
  if (Math.abs(nowSec - timestamp) > toleranceSec) return { ok: false, reason: "timestamp outside tolerance (replay?)" };

  const signedPayload = `${parts.t}.${rawBody}`;                   // timestamp . rawBody
  const expected = crypto.createHmac("sha256", secret).update(signedPayload).digest("hex");
  const a = Buffer.from(expected), b = Buffer.from(parts.v1 ?? "");
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return { ok: false, reason: "signature mismatch" };
  return { ok: true };
}

