// All amounts in cents. remainingFraction = daysLeft / daysInPeriod.
function proration(oldCents: number, newCents: number, daysLeft: number, daysInPeriod: number) {
  const remaining = daysLeft / daysInPeriod;
  const credit = Math.round(oldCents * remaining);   // refund unused old plan
  const charge = Math.round(newCents * remaining);   // pay for remaining new plan
  const net = charge - credit;                        // what the customer owes now
  return { credit, charge, net };
}
