type Outcome = "success" | "failure";
// attempts: the scheduled retry results after the first failure.
function runDunning(attempts: Outcome[], maxRetries: number, terminal: "canceled" | "unpaid") {
  let state = "past_due", used = 0;
  for (const a of attempts) {
    if (used >= maxRetries) break;
    used++;
    if (a === "success") { state = "active"; break; }   // recovered
  }
  if (state === "past_due" && used >= maxRetries) state = terminal;   // exhausted
  return { state, retriesUsed: used };
}

