// A field looks like a raw PAN if it is a 13–19 digit number under a card-ish key.
function looksLikePAN(key: string, value: unknown): boolean {
  const cardKey = /card|pan|number|cc/i.test(key);
  const digits = typeof value === "string" ? value.replace(/\s|-/g, "") : "";
  return cardKey && /^\d{13,19}$/.test(digits);
}

function scopeLint(payload: Record<string, unknown>): string[] {
  const findings: string[] = [];
  for (const [k, v] of Object.entries(payload)) {
    if (looksLikePAN(k, v)) findings.push("raw PAN received in field '" + k + "' -> expands PCI scope");
  }
  return findings;   // empty means token/id-only, SAQ A-friendly
}

